  "AVD-AZU-0042": { kind: 'EXAMPLE', lang: "terraform", code: "resource \"azurerm_kubernetes_cluster\" \"good_example\" {\n  // azurerm < 2.99.0\n  role_based_access_control {\n    enabled = true\n  }\n}" },
