  // Object versioning in Cloud Storage is recommended to protect against accidental or malicious deletio
  "AVD-GCP-0078": { kind: 'EXAMPLE', lang: "terraform", code: "resource \"google_storage_bucket\" \"default\" {\n  name                        = \"my-default-bucket\"\n  location                    = \"EU\"\n  force_destroy               = true\n  uniform_bucket_level_access = true\n\n  versioning {\n    enabled = true\n  }\n}" },
