  "AVD-GCP-0079": { kind: 'EXAMPLE', lang: "terraform", code: "resource \"google_project_iam_audit_config\" \"config\" {\n  project = \"your-project-id\"\n  service = \"allServices\"\n  audit_log_config {\n    log_type = \"ADMIN_READ\"\n  }\n  audit_log_config {\n    log_type = \"DATA_READ\"\n  }\n  audit_log_config {\n    log_type = \"DATA_WRITE\"\n  }\n}" },
